using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using MiniErp.Data;using MiniErp.Models;namespace MiniErp.Controllers;public class InvoicesController(AppDbContext db):Controller{public IActionResult Index(InvoiceType? type,InvoiceStatus? status){var q=db.Invoices.AsNoTracking().Include(x=>x.Payments).AsQueryable();if(type.HasValue)q=q.Where(x=>x.Type==type);if(status.HasValue)q=q.Where(x=>x.Status==status);return View(q.OrderByDescending(x=>x.IssueDate).ToArray());}public IActionResult Details(int id){var x=db.Invoices.AsNoTracking().Include(x=>x.Payments).FirstOrDefault(x=>x.Id==id);return x is null?NotFound():View(x);}[HttpPost,ValidateAntiForgeryToken]public IActionResult FromSale(int id,string series="V",decimal taxRate=21){var o=db.SalesOrders.Include(x=>x.Lines).FirstOrDefault(x=>x.Id==id);if(o is null||o.Status!=SalesOrderStatus.Completed)return BadRequest();if(db.Invoices.Any(x=>x.SalesOrderId==id))return RedirectToAction(nameof(Index));return Create(InvoiceType.Sale,series,taxRate,o.Total,id,null);}[HttpPost,ValidateAntiForgeryToken]public IActionResult FromPurchase(int id,string series="C",decimal taxRate=21){var o=db.PurchaseOrders.Include(x=>x.Lines).FirstOrDefault(x=>x.Id==id);if(o is null||o.Status!=PurchaseOrderStatus.Received)return BadRequest();if(db.Invoices.Any(x=>x.PurchaseOrderId==id))return RedirectToAction(nameof(Index));return Create(InvoiceType.Purchase,series,taxRate,o.Total,null,id);}[HttpPost,ValidateAntiForgeryToken]public IActionResult Issue(int id){var x=db.Invoices.Find(id);if(x is null)return NotFound();if(x.Status==InvoiceStatus.Draft){x.Status=InvoiceStatus.Issued;db.SaveChanges();}return RedirectToAction(nameof(Details),new{id});}[HttpPost,ValidateAntiForgeryToken]public IActionResult Pay(int id,decimal amount,string method){var x=db.Invoices.Include(x=>x.Payments).FirstOrDefault(x=>x.Id==id);if(x is null)return NotFound();if(x.Status!=InvoiceStatus.Issued||amount<=0||amount>x.Outstanding)return BadRequest();x.Payments.Add(new(){Amount=amount,Method=method,Date=DateTime.Today});if(amount==x.Outstanding)x.Status=InvoiceStatus.Paid;db.SaveChanges();return RedirectToAction(nameof(Details),new{id});}[HttpPost,ValidateAntiForgeryToken]public IActionResult Cancel(int id){var x=db.Invoices.Include(x=>x.Payments).FirstOrDefault(x=>x.Id==id);if(x is null)return NotFound();if(x.Payments.Count==0&&x.Status!=InvoiceStatus.Paid){x.Status=InvoiceStatus.Cancelled;db.SaveChanges();}return RedirectToAction(nameof(Details),new{id});}private IActionResult Create(InvoiceType type,string series,decimal rate,decimal basis,int? sale,int? purchase){series=series.Trim().ToUpperInvariant();var next=db.Invoices.Where(x=>x.Series==series).Select(x=>(int?)x.Id).Max()??0;var x=new Invoice{Type=type,Series=series,Number=$"{DateTime.Today.Year}-{next+1:00000}",TaxBase=basis,TaxRate=rate,TaxAmount=decimal.Round(basis*rate/100,2),SalesOrderId=sale,PurchaseOrderId=purchase};x.Total=x.TaxBase+x.TaxAmount;db.Add(x);db.SaveChanges();return RedirectToAction(nameof(Details),new{id=x.Id});}}